export function WantlistExport({ watchlist, api }) {
  const [open, setOpen] = useState(false);
  const [withSet, setWithSet] = useState(false);
  const [busy, setBusy] = useState(false);
  const [names, setNames] = useState(null);
  const [msg, setMsg] = useState('');

  const lookup = async () => {
    setBusy(true); setMsg('');
    try {
      const ids = watchlist.map((c) => c.id).filter((id) => isReal(id) && !String(id).startsWith('cm-'));
      const out = {};
      for (let i = 0; i < ids.length; i += 100) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 90000);
        const res = await fetch(`${api}/api/wantlist-names`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, signal: controller.signal, body: JSON.stringify({ ids: ids.slice(i, i + 100) }) });
        clearTimeout(timer);
        if (!res.ok) throw new Error(`Server antwortet mit Status ${res.status}`);
        Object.assign(out, (await res.json()).names || {});
      }
      setNames(out);
    } catch (e) {
      setNames({});
      setMsg(e.name === 'AbortError'
        ? 'Der Server hat nicht geantwortet – es wurden die gespeicherten (evtl. deutschen) Namen verwendet. Später nochmal versuchen für englische Namen.'
        : 'Englische Namen konnten nicht geladen werden – es wurden die gespeicherten Namen verwendet.');
    } finally {
      setBusy(false);
    }
  };

  const toggle = async () => {
    const next = !open;
    setOpen(next);
    if (next && names === null && watchlist.length > 0) await lookup();
  };

  const text = useMemo(() => {
    if (!names) return '';
    const rows = watchlist.map((c) => {
      const n = names[c.id];
      const isCm = String(c.id).startsWith('cm-');
      let name = n?.name || (isCm ? String(c.name || '') : plain(c.name));
      const extra = n ? [...(n.abilities || []), ...(n.attacks || [])] : [];
      if (extra.length) name = `${name} ${extra.join(' ')}`;
      else if (isCm) { const m = name.match(/^([^\[']*?)\s*\[(.*)\]\s*$/); if (m) name = `${m[1]} ${m[2].split('|').map((a) => a.trim()).join(' ')}`; }
      const rawSet = n?.set || c.set?.name || '';
      const set = /^Cardmarket-Set /.test(rawSet) ? '' : rawSet;
      return { name, set };
    }).filter((r) => r.name);
    rows.sort((a, b) => a.set.localeCompare(b.set) || a.name.localeCompare(b.name));
    return rows.map((r) => `1x ${r.name}${withSet && r.set ? ` (${r.set})` : ''}`).join('\n');
  }, [names, watchlist, withSet]);

  const copy = async () => {
    try { await navigator.clipboard.writeText(text); setMsg('Kopiert. ✓ Auf Cardmarket: Wants Lists → Liste öffnen → „Add Deck List“ → einfügen.'); }
    catch (e) { window.prompt('Zum Kopieren markieren:', text); }
  };

  if (watchlist.length === 0) return null;

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-xl p-3 space-y-2">
      <button onClick={toggle} className="w-full flex items-center justify-between text-left">
        <span className="text-sm font-bold text-slate-100">📤 Als Cardmarket-Wantlist exportieren</span>
        <span className="text-xs text-cyan-400">{open ? 'Schließen' : 'Öffnen'}</span>
      </button>
      {open && (
        <div className="space-y-2">
          {busy && <p className="text-xs text-cyan-400 animate-pulse">Hole englische Namen … (Server braucht evtl. bis zu einer Minute)</p>}
          {!busy && names && (
            <>
              <label className="flex items-center gap-2 text-xs text-slate-300">
                <input type="checkbox" checked={withSet} onChange={(e) => setWithSet(e.target.checked)} className="accent-cyan-500" />
                Set-Name in Klammern anhängen (genauer, aber Cardmarket muss die Schreibweise kennen)
              </label>
              <textarea readOnly value={text} rows={Math.min(12, text.split('\n').length + 1)} className="w-full bg-slate-950 border border-slate-800 text-slate-300 rounded-lg p-2 text-xs font-mono outline-none" />
              <div className="flex gap-2">
                <button onClick={copy} className="flex-1 bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-black text-xs py-2 rounded-lg">Kopieren</button>
                <button onClick={() => downloadText(`wantlist-${today()}.txt`, text + '\n', 'text/plain;charset=utf-8')} className="flex-1 bg-slate-800 hover:bg-slate-700 text-cyan-300 border border-cyan-500/30 font-bold text-xs py-2 rounded-lg">Als .txt speichern</button>
              </div>
              <p className="text-[10px] text-slate-500">Auf Cardmarket meldet der Import Zeilen, die er nicht zuordnen konnte – dann die Option „Set-Name“ ausschalten und erneut einfügen.</p>
            </>
          )}
          {msg && <p className="text-[11px] text-slate-300">{msg}</p>}
        </div>
      )}
    </div>
  );
}

// Batch-Import per Foto: ein Foto einer Binder-Seite (z. B. 3×3) wird in Felder zerlegt,
// jedes Feld gescannt, gesucht und geprüft.
// Danach kannst du die Treffer kontrollieren und alle auf einmal in die Collection legen.
import React, { useState, useRef, useEffect } from 'react';
import { readCard, loadImageSource } from './CardScanner';
import { coverRect, buildQuery } from './scanParse';
import { rankByImage } from './imageMatch';
import { watchPrice } from './priceData';
import { OwnedBadge } from './Backup';

const VARIANT_LABEL = { normal: 'Normal', reverse: 'Reverse Holo', holo: 'Holo', firstEdition: '1st Edition' };
// Welche Varianten gibt es für die Karte? (TCGdex-Flags; ohne Angabe nur Normal)
const availKeys = (card) => {
  const f = card && card.variants;
  if (!f) return ['normal'];
  const keys = Object.keys(VARIANT_LABEL).filter((k) => f[k]);
  return keys.length ? keys : ['normal'];
};
// Gewünschte (erkannte oder gewählte) Variante, falls es sie gibt – sonst die erste verfügbare
const effVariant = (c, card) => {
  const keys = availKeys(card);
  return c.variant && keys.includes(c.variant) ? c.variant : keys[0];
};

const plain = (n) => String(n || '').replace(/\s*\[.*\]\s*$/, '');
const eur = (n) => `${(Number(n) || 0).toFixed(2).replace('.', ',')} €`;

// Raster über das Foto legen (trim = Rand in %, der auf allen Seiten abgeschnitten wird)
function cellRects(w, h, rows, cols, trim) {
  const tx = (w * trim) / 100;
  const ty = (h * trim) / 100;
  const cw = (w - 2 * tx) / cols;
  const ch = (h - 2 * ty) / rows;
  const out = [];
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < cols; c += 1) out.push({ x: tx + c * cw, y: ty + r * ch, w: cw, h: ch });
  }
  return out;
}

// Aus einem Feld das größte mittige 5:7-Rechteck (Kartenformat) ausschneiden
function cellCanvas(source, rect) {
  const { sx, sy, sw } = coverRect(rect.w, rect.h);
  const sh = (sw * 7) / 5;
  const outW = Math.min(800, Math.round(sw));
  const c = document.createElement('canvas');
  c.width = outW;
  c.height = Math.round((outW * 7) / 5);
  c.getContext('2d').drawImage(source, rect.x + sx, rect.y + sy, sw, Math.min(sh, rect.h), 0, 0, c.width, c.height);
  return c;
}

function smallThumb(canvas) {
  const c = document.createElement('canvas');
  c.width = 140;
  c.height = 196;
  c.getContext('2d').drawImage(canvas, 0, 0, 140, 196);
  try { return c.toDataURL('image/jpeg', 0.6); } catch (e) { return ''; }
}

export default function BatchScanner({ onClose, onSearch, onAdd, Img, api, conditions, languages, defaultCondition, defaultLanguage, owned }) {
  const [step, setStep] = useState('setup'); // setup | review
  const [photo, setPhoto] = useState(null); // { url, w, h, source }
  const [rows, setRows] = useState(3);
  const [cols, setCols] = useState(3);
  const [trim, setTrim] = useState(3);
  const [cells, setCells] = useState([]);
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState('');
  const [error, setError] = useState('');
  const [cond, setCond] = useState(defaultCondition);
  const [lang, setLang] = useState(defaultLanguage);
  const [adding, setAdding] = useState(false);

  const aliveRef = useRef(true);
  const canvases = useRef([]);
  const urlRef = useRef(null);

  useEffect(() => {
    aliveRef.current = true;
    return () => {
      aliveRef.current = false;
      if (urlRef.current) URL.revokeObjectURL(urlRef.current);
    };
  }, []);

  const patch = (i, p) => setCells((prev) => prev.map((c) => (c.idx === i ? { ...c, ...p } : c)));

  const onFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file) return;
    setError('');
    try {
      const { source, w, h } = await loadImageSource(file);
      if (urlRef.current) URL.revokeObjectURL(urlRef.current);
      const url = URL.createObjectURL(file);
      urlRef.current = url;
      setPhoto({ url, w, h, source });
    } catch (err) {
      setError('Das Foto konnte nicht gelesen werden.');
    }
  };

  // Name/Nummer suchen (erst mit Nummer, sonst nur Name), mehrere Treffer per Bildvergleich sortieren
  const lookup = async (name, number, canvas) => {
    const nm = String(name || '').trim();
    if (!nm) return { cards: [], scores: {} };
    let list = await onSearch(buildQuery(nm, number));
    if (list.length === 0 && number) list = await onSearch(nm);
    if (list.length > 1 && canvas) {
      try { return await rankByImage(canvas, list, api, 8); } catch (e) { /* ohne Bildvergleich */ }
    }
    return { cards: list, scores: {} };
  };

  const run = async () => {
    if (!photo || running) return;
    const rects = cellRects(photo.w, photo.h, rows, cols, trim);
    canvases.current = [];
    setError('');
    setStep('review');
    setRunning(true);
    setCells(rects.map((_, i) => ({ idx: i, status: 'wait', name: '', number: '', thumb: '', cards: [], scores: {}, sel: -1, include: false, variant: '', vAuto: false })));

    try {
      for (let i = 0; i < rects.length; i += 1) {
        if (!aliveRef.current) return;
        setProgress(`Karte ${i + 1} / ${rects.length} wird gescannt …`);
        const canvas = cellCanvas(photo.source, rects[i]);
        canvases.current[i] = canvas;
        const base64Image = canvas.toDataURL('image/jpeg', 0.85);

        let name = '';
        let number = '';
        let foundCards = [];
        let scores = {};
        let status = 'none';
        let variant = '';

        try {
          const scanResult = await readCard(base64Image);
          name = scanResult.aiAnalysis?.name || '';
          number = scanResult.aiAnalysis?.number || '';
          variant = scanResult.aiAnalysis?.variant || '';
          foundCards = scanResult.results || [];

          // Fallback-Suche, falls Backend-Ergebnis leer ist, aber ein Name/Nummer erkannt wurde
          if (foundCards.length === 0 && (name || number)) {
            const fallback = await lookup(name, number, canvas);
            foundCards = fallback.cards || [];
            scores = fallback.scores || {};
          }

          status = foundCards.length ? 'ok' : 'none';
        } catch (e) {
          status = 'error';
        }

        if (!aliveRef.current) return;
        patch(i, {
          status,
          name,
          number,
          thumb: smallThumb(canvas),
          cards: foundCards,
          scores,
          sel: foundCards.length ? 0 : -1,
          include: foundCards.length > 0,
          variant,
          vAuto: !!variant
        });
      }
    } catch (e) {
      if (aliveRef.current) setError('Analyse fehlgeschlagen: ' + ((e && e.message) || 'Unbekannter Fehler'));
    } finally {
      if (aliveRef.current) { setRunning(false); setProgress(''); }
    }
  };

  const research = async (i) => {
    const c = cells[i];
    patch(i, { status: 'wait' });
    try {
      const found = await lookup(c.name, c.number, canvases.current[i]);
      patch(i, { status: found.cards.length ? 'ok' : 'none', cards: found.cards, scores: found.scores, sel: found.cards.length ? 0 : -1, include: found.cards.length > 0 });
    } catch (e) { patch(i, { status: 'error' }); }
  };

  const chosenOf = (c) => (c.sel >= 0 ? c.cards[c.sel] : null);
  const count = cells.filter((c) => c.include && chosenOf(c)).length;

  const doAdd = async () => {
    const picked = new Map();
    cells.forEach((c) => {
      const card = chosenOf(c);
      if (!c.include || !card) return;
      const variant = effVariant(c, card);
      const key = `${card.id}|${variant}`;
      const e = picked.get(key) || { card, qty: 0, variant };
      e.qty += 1;
      picked.set(key, e);
    });
    if (picked.size === 0) return;
    setAdding(true);
    try {
      const ok = await onAdd([...picked.values()], cond, lang);
      if (ok === false) { setAdding(false); return; } // Duplikat-Warnung abgebrochen
      onClose();
    } catch (e) {
      setError('Hinzufügen fehlgeschlagen: ' + ((e && e.message) || 'Unbekannter Fehler'));
      setAdding(false);
    }
  };

  const inputCls = 'w-full bg-slate-950 border border-slate-700 focus:border-cyan-500 text-slate-100 rounded-md px-2 py-1 text-xs outline-none';
  const pill = (active) => `px-3 py-1.5 rounded-lg text-xs font-bold border ${active ? 'bg-cyan-500 text-slate-950 border-cyan-500' : 'bg-slate-950 text-slate-400 border-slate-800'}`;

  return (
    <div className="fixed inset-0 z-[80] bg-slate-950 flex flex-col text-slate-100">
      <div className="flex items-center justify-between px-4 py-3 border-b border-cyan-500/20 bg-slate-900">
        <h2 className="font-black text-cyan-400 text-sm">🗂️ Mehrere Karten per Foto</h2>
        <button onClick={onClose} className="text-xs bg-slate-800 px-3 py-1.5 rounded-lg text-slate-300 hover:text-rose-400">Schließen ✕</button>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        {step === 'setup' && (
          <div className="space-y-4 max-w-xl mx-auto">
            <p className="text-xs text-slate-400">
              Fotografiere eine ganze Binder-Seite (oder Karten in einem Raster) von oben, gerade und ohne Blitz-Reflexe.
              Stelle unten Reihen und Spalten ein, sodass das Raster genau über den Karten liegt.
            </p>
            <label className="block text-center cursor-pointer bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-black py-3 rounded-xl text-sm transition-colors">
              📷 Foto aufnehmen / auswählen
              <input type="file" accept="image/*" onChange={onFile} className="hidden" />
            </label>
            {error && <p className="text-xs text-amber-300">{error}</p>}

            {photo && (
              <>
                <div className="relative rounded-xl overflow-hidden border border-slate-700 bg-black">
                  <img src={photo.url} alt="Foto" className="w-full block" />
                  <div
                    className="absolute grid pointer-events-none"
                    style={{ left: `${trim}%`, right: `${trim}%`, top: `${trim}%`, bottom: `${trim}%`, gridTemplateColumns: `repeat(${cols}, 1fr)`, gridTemplateRows: `repeat(${rows}, 1fr)` }}
                  >
                    {Array.from({ length: rows * cols }, (_, i) => (
                      <div key={i} className="border border-dashed border-cyan-300/80 flex items-start justify-start">
                        <span className="text-[10px] bg-slate-950/70 text-cyan-300 px-1 rounded-br">{i + 1}</span>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <p className="text-[10px] text-slate-400 mb-1">Reihen</p>
                    <div className="flex gap-1">{[1, 2, 3, 4, 5].map((n) => <button key={n} onClick={() => setRows(n)} className={`flex-1 ${pill(rows === n)}`}>{n}</button>)}</div>
                  </div>
                  <div>
                    <p className="text-[10px] text-slate-400 mb-1">Spalten</p>
                    <div className="flex gap-1">{[1, 2, 3, 4, 5].map((n) => <button key={n} onClick={() => setCols(n)} className={`flex-1 ${pill(cols === n)}`}>{n}</button>)}</div>
                  </div>
                </div>
                <label className="block text-[10px] text-slate-400">
                  Rand abschneiden: {trim} %
                  <input type="range" min="0" max="20" value={trim} onChange={(e) => setTrim(Number(e.target.value))} className="w-full accent-cyan-500" />
                </label>
                <button onClick={run} className="w-full bg-cyan-500 hover:bg-cyan-400 text-slate-950 font-black py-3 rounded-xl text-sm transition-colors">
                  🔍 {rows * cols} Karten erkennen
                </button>
              </>
            )}
          </div>
        )}

        {step === 'review' && (
          <div className="space-y-3 max-w-3xl mx-auto">
            {running && (
              <div className="bg-slate-900 border border-cyan-500/30 rounded-xl p-3 text-xs text-cyan-300 flex items-center gap-2">
                <span className="animate-spin">⚡</span> {progress}
              </div>
            )}
            {error && <p className="text-xs text-amber-300">{error}</p>}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {cells.map((c, i) => {
                const chosen = chosenOf(c);
                const score = chosen ? c.scores[chosen.id] : null;
                return (
                  <div key={c.idx} className={`bg-slate-900 border rounded-xl p-2 space-y-2 ${c.include ? 'border-cyan-500/50' : 'border-slate-800'}`}>
                    <div className="flex gap-2">
                      <div className="w-16 shrink-0">
                        {c.thumb ? <img src={c.thumb} alt="Foto" className="w-full rounded border border-slate-800" /> : <div className="aspect-[5/7] rounded border border-dashed border-slate-700" />}
                        <p className="text-[9px] text-slate-500 text-center mt-0.5">Platz {Math.floor(i / cols) + 1}/{(i % cols) + 1}</p>
                      </div>
                      <div className="w-16 shrink-0">
                        {chosen
                          ? <Img src={chosen.images && chosen.images.small} alt={chosen.name} className="w-full rounded" />
                          : <div className="aspect-[5/7] rounded border border-dashed border-slate-700 flex items-center justify-center text-slate-600 text-lg">{c.status === 'wait' ? '…' : '?'}</div>}
                        <p className="text-[9px] text-slate-500 text-center mt-0.5">Treffer</p>
                      </div>
                      <div className="flex-1 min-w-0 space-y-1">
                        <div className="grid grid-cols-3 gap-1">
                          <input value={c.name} onChange={(e) => patch(i, { name: e.target.value })} placeholder="Name" className={`col-span-2 ${inputCls}`} />
                          <input value={c.number} onChange={(e) => patch(i, { number: e.target.value })} placeholder="44/102" className={inputCls} />
                        </div>
                        <select
                          value={c.sel}
                          onChange={(e) => { const sel = Number(e.target.value); patch(i, { sel, include: sel >= 0 }); }}
                          className={inputCls}
                          disabled={c.cards.length === 0}
                        >
                          <option value={-1}>{c.cards.length ? '— keine —' : 'Kein Treffer'}</option>
                          {c.cards.slice(0, 12).map((card, k) => (
                            <option key={card.id} value={k}>
                              {plain(card.name)}{card.number ? ` #${card.number}` : ''} · {(card.set && card.set.name) || '?'}{c.scores[card.id] != null ? ` · ${c.scores[card.id]} %` : ''}
                            </option>
                          ))}
                        </select>
                        {chosen && (
                          <p className="text-[10px] text-slate-400 truncate">
                            <span className="text-cyan-400 font-bold">{eur(watchPrice(chosen.cardmarket && chosen.cardmarket.prices))}</span>
                            {score != null ? ` · Bildähnlichkeit ${score} %` : ''}
                          </p>
                        )}
                        {chosen && owned && <OwnedBadge info={owned.get(chosen.id)} />}
                        {chosen && availKeys(chosen).length > 1 && (() => {
                          const eff = effVariant(c, chosen);
                          return (
                            <div>
                              <select value={eff} onChange={(e) => patch(i, { variant: e.target.value, vAuto: false })} className={inputCls}>
                                {availKeys(chosen).map((k) => <option key={k} value={k}>{VARIANT_LABEL[k]}</option>)}
                              </select>
                              {c.vAuto && c.variant === eff && <p className="text-[9px] text-amber-300 mt-0.5">automatisch erkannt – bitte prüfen</p>}
                            </div>
                          );
                        })()}
                      </div>
                    </div>
                    <div className="flex items-center justify-between gap-2">
                      <label className="flex items-center gap-2 text-xs text-slate-300">
                        <input type="checkbox" checked={c.include && !!chosen} disabled={!chosen} onChange={(e) => patch(i, { include: e.target.checked })} className="accent-cyan-500" />
                        Hinzufügen
                      </label>
                      <span className="text-[10px] text-slate-500">
                        {c.status === 'wait' && 'wird analysiert …'}
                        {c.status === 'none' && (c.name ? 'nichts gefunden' : 'leer / nicht erkannt')}
                        {c.status === 'error' && 'Suche fehlgeschlagen'}
                      </span>
                      <button onClick={() => research(i)} disabled={running || c.status === 'wait'} className="text-[11px] font-bold text-cyan-400 hover:underline disabled:opacity-40">Neu suchen</button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {step === 'review' && (
        <div className="border-t border-cyan-500/20 bg-slate-900 p-3 space-y-2">
          <div className="grid grid-cols-2 gap-2 max-w-3xl mx-auto">
            <select value={cond} onChange={(e) => setCond(e.target.value)} className="bg-slate-950 border border-slate-700 text-slate-200 rounded-lg p-2 text-xs">
              {conditions.map((c) => <option key={c.name} value={c.name}>{c.name}</option>)}
            </select>
            <select value={lang} onChange={(e) => setLang(e.target.value)} className="bg-slate-950 border border-slate-700 text-slate-200 rounded-lg p-2 text-xs">
              {languages.map((l) => <option key={l.name} value={l.name}>{l.name}</option>)}
            </select>
          </div>
          <div className="flex gap-2 max-w-3xl mx-auto">
            <button onClick={() => { if (!running) { setStep('setup'); setCells([]); } }} disabled={running} className="flex-1 bg-slate-800 hover:bg-slate-700 disabled:opacity-40 text-slate-200 font-bold py-3 rounded-xl text-sm border border-slate-700">← Anderes Foto</button>
            <button onClick={doAdd} disabled={adding || running || count === 0} className="flex-[2] bg-cyan-500 hover:bg-cyan-400 disabled:opacity-40 text-slate-950 font-black py-3 rounded-xl text-sm transition-colors">
              {adding ? '⏳ Speichere …' : `➕ ${count} Karten zur Collection`}
            </button>
          </div>
          <p className="text-[10px] text-slate-500 text-center">Zustand und Sprache gelten für alle Karten dieses Fotos. Die Variante ist ein Vorschlag aus dem Foto (bitte prüfen), der Preis wird automatisch gesetzt. Beides lässt sich später in der Collection bearbeiten.</p>
        </div>
      )}
    </div>
  );
}

// Karten-Scanner (Backend: POST /api/scan-genai).
// Passt zu den Aufrufen in App.jsx:
//   <CardScanner mode="collection"|"search" onClose onResult onSearch onPick Img owned api series onSeriesChange history onUndo />
// Exportiert außerdem readCard + loadImageSource für BatchScanner.jsx.
import React, { useState, useRef, useEffect } from 'react';
import { buildQuery } from './scanParse';
import { rankByImage } from './imageMatch';
import { watchPrice } from './priceData';
import { OwnedBadge } from './Backup';
import { auth } from './firebase';

const API_URL = import.meta.env.VITE_API_URL || 'https://pokemon-backend-x7l7.onrender.com';

const plain = (n) => String(n || '').replace(/\s*\[.*\]\s*$/, '');
const eur = (n) => `${(Number(n) || 0).toFixed(2).replace('.', ',')} €`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const LANG_LABEL = { de: 'Deutsch', en: 'Englisch', ja: 'Japanisch', ko: 'Koreanisch', zh: 'Chinesisch' };

// ==========================================
// Exporte für BatchScanner
// ==========================================
export const loadImageSource = (file) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = reject;
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = reject;
      img.onload = () => resolve({ source: img, w: img.naturalWidth || img.width, h: img.naturalHeight || img.height });
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });

// Ein Versuch. Der Server wiederholt bei Überlastung selbst.
async function readCardOnce(base64Image, api) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 90000); // Render-Gratisplan kann schlafen
  try {
    const user = auth.currentUser;
    if (!user) { const e = new Error('Bitte melde dich an, um zu scannen.'); e.final = true; throw e; }
    let token;
    try { token = await user.getIdToken(); } catch (err) {
      const e = new Error('Die Anmeldung konnte nicht erneuert werden. Internet prüfen oder neu anmelden.'); e.busy = true; throw e;
    }
    const response = await fetch(`${api}/api/scan-genai`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      signal: controller.signal,
      body: JSON.stringify({ image: base64Image })
    });
    const data = await response.json().catch(() => ({}));
    if (response.status === 401) { const e = new Error('Anmeldung abgelaufen oder ungültig. Bitte neu anmelden.'); e.final = true; throw e; }
    if (response.status === 429) { const e = new Error('Zu viele Scans auf einmal. Bitte kurz warten.'); e.final = true; throw e; }
    if (response.status === 503) { const e = new Error('Der Scan ist gerade ausgelastet. Bitte warte kurz und scanne erneut.'); e.busy = true; throw e; }
    if (!response.ok) { const e = new Error(data.error || `Fehler beim Scannen (Status ${response.status}).`); e.final = true; throw e; }
    return data;
  } catch (e) {
    if (e.name === 'AbortError') { const t = new Error('Der Server hat nicht geantwortet (schläft evtl.). Bitte gleich nochmal versuchen.'); t.busy = true; throw t; }
    if (e instanceof TypeError) { const t = new Error('Keine Verbindung zum Server. Internet prüfen und erneut versuchen.'); t.busy = true; throw t; }
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

// Mit einer automatischen Wiederholung (nach 3 s) bei Überlastung/Netzfehler
export const readCard = async (base64Image, api = API_URL, { retries = 1 } = {}) => {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await readCardOnce(base64Image, api);
    } catch (e) {
      if (!e.busy || attempt >= retries) throw e;
      await sleep(3000);
    }
  }
};

// Foto verkleinern (schneller Upload, unter dem 10-MB-Limit des Servers)
function shrinkToCanvas(source, w, h, maxSide = 900) {
  const scale = Math.min(1, maxSide / Math.max(w, h));
  const c = document.createElement('canvas');
  c.width = Math.round(w * scale);
  c.height = Math.round(h * scale);
  c.getContext('2d').drawImage(source, 0, 0, c.width, c.height);
  return c;
}

// ==========================================
// Scan-Verlauf mit „Rückgängig“ (auch in App.jsx unter der Collection genutzt)
// ==========================================
const hhmm = (ts) => new Date(ts).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });

export function ScanHistory({ history = [], onUndo, onClear, Img, compact = false }) {
  const [busyId, setBusyId] = useState(null);
  if (!history.length || !onUndo) return null;
  const Pic = Img || 'img';

  const undo = async (entry) => {
    if (busyId) return;
    setBusyId(entry.docId);
    try { await onUndo(entry); } finally { setBusyId(null); }
  };

  return (
    <div className="bg-slate-900 border border-amber-500/30 rounded-xl p-3 space-y-2">
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-xs font-bold text-amber-300">🕘 Zuletzt gescannt ({history.length})</h3>
        {onClear && !compact && <button onClick={onClear} className="text-[11px] text-slate-400 hover:text-slate-200 underline">Liste leeren</button>}
      </div>
      <ul className="space-y-1.5">
        {history.slice(0, compact ? 5 : 30).map((h) => (
          <li key={h.docId} className="flex items-center gap-2 bg-slate-950 border border-slate-800 rounded-lg p-1.5">
            <Pic src={h.image} alt={h.name} className="w-8 rounded shrink-0" />
            <div className="min-w-0 flex-1">
              <p className="text-xs font-bold text-slate-200 truncate">{h.name}{h.number ? <span className="text-slate-500 font-normal"> #{h.number}</span> : null}</p>
              <p className="text-[10px] text-slate-500 truncate">{h.set || 'Unbekanntes Set'} · {h.condition}{h.variant && h.variant !== 'normal' ? ` · ${h.variant === 'reverse' ? 'Reverse Holo' : h.variant === 'holo' ? 'Holo' : h.variant}` : ''} · {hhmm(h.at)}</p>
            </div>
            <button
              onClick={() => undo(h)}
              disabled={!!busyId}
              className="shrink-0 text-[11px] font-black px-2.5 py-1 rounded-lg border bg-slate-900 text-rose-300 border-rose-500/40 hover:bg-rose-500 hover:text-slate-950 disabled:opacity-50"
            >{busyId === h.docId ? '…' : '↩ Rückgängig'}</button>
          </li>
        ))}
      </ul>
      <p className="text-[10px] text-slate-500">Rückgängig löscht den Eintrag wieder aus der Collection{compact ? '' : ' (stammt die Karte von der Watchlist, kommt sie dorthin zurück)'}.</p>
    </div>
  );
}

// ==========================================
// Komponente
// ==========================================
export default function CardScanner({ mode = 'collection', onClose, onResult, onSearch, onPick, Img, owned, api = API_URL, series = false, onSeriesChange, history = [], onUndo }) {
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState('');
  const [error, setError] = useState('');
  const [preview, setPreview] = useState('');
  const [scanned, setScanned] = useState(false);
  const [name, setName] = useState('');
  const [number, setNumber] = useState('');
  const [meta, setMeta] = useState({ set: '', language: '' });
  const [variant, setVariant] = useState('');          // erkannte/gewählte Variante ('' = unbekannt)
  const [variantAuto, setVariantAuto] = useState(false); // true = vom Modell vorgeschlagen, nicht bestätigt
  const [cards, setCards] = useState([]);
  const [scores, setScores] = useState({});
  const canvasRef = useRef(null);
  const dataUrlRef = useRef('');
  const aliveRef = useRef(true);

  useEffect(() => {
    aliveRef.current = true;
    return () => { aliveRef.current = false; };
  }, []);

  // Treffer werden sofort angezeigt; der Bildvergleich läuft im Hintergrund und sortiert danach nur um
  const rankToken = useRef(0);
  const rankInBackground = (list) => {
    rankToken.current += 1;
    const token = rankToken.current;
    const canvas = canvasRef.current;
    if (list.length < 2 || !canvas) return;
    rankByImage(canvas, list, api, 8)
      .then((r) => {
        if (aliveRef.current && rankToken.current === token) { setCards(r.cards); setScores(r.scores); }
      })
      .catch(() => { /* ohne Bildvergleich */ });
  };

  // Analysiert das aktuelle Foto (auch für „Erneut versuchen“, ohne neu zu fotografieren)
  const analyze = async (dataUrl) => {
    setBusy(true); setError(''); setScanned(false); setCards([]); setScores({});
    setStatus('Karte wird gescannt …');
    try {
      const data = await readCard(dataUrl, api);
      if (!aliveRef.current) return;
      const ai = data.aiAnalysis || {};
      setName(ai.name || '');
      setNumber(ai.number || '');
      setMeta({ set: ai.set || '', language: ai.language || '' });
      setVariant(ai.variant || '');
      setVariantAuto(!!ai.variant);

      let list = Array.isArray(data.results) ? data.results : [];
      if (list.length === 0 && ai.name && onSearch) {
        setStatus('Suche in der Datenbank …');
        try { list = await onSearch(buildQuery(ai.name, ai.number)); } catch (err) { /* unten: kein Treffer */ }
        if (list.length === 0 && ai.number) { try { list = await onSearch(ai.name); } catch (err) { /* egal */ } }
      }
      if (!aliveRef.current) return;
      setCards(list);
      setScores({});
      setScanned(true);
      rankInBackground(list);
    } catch (err) {
      if (aliveRef.current) setError(err.message || 'Scan fehlgeschlagen.');
    } finally {
      if (aliveRef.current) { setBusy(false); setStatus(''); }
    }
  };

  const onFile = async (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = '';
    if (!file || busy) return;
    setError('');
    try {
      const { source, w, h } = await loadImageSource(file);
      const canvas = shrinkToCanvas(source, w, h);
      canvasRef.current = canvas;
      dataUrlRef.current = canvas.toDataURL('image/jpeg', 0.8);
      setPreview(dataUrlRef.current);
      await analyze(dataUrlRef.current);
    } catch (err) {
      setError('Das Foto konnte nicht gelesen werden.');
    }
  };

  const research = async () => {
    if (!name.trim() || !onSearch || busy) return;
    setBusy(true); setError(''); setStatus('Suche in der Datenbank …');
    try {
      let list = await onSearch(buildQuery(name, number));
      if (list.length === 0 && number) list = await onSearch(name.trim());
      if (!aliveRef.current) return;
      setCards(list);
      setScores({});
      setScanned(true);
      rankInBackground(list);
    } catch (err) {
      if (aliveRef.current) setError(err.message || 'Suche fehlgeschlagen.');
    } finally {
      if (aliveRef.current) { setBusy(false); setStatus(''); }
    }
  };

  const takeToSearch = () => {
    if (!name.trim() || !onResult) return;
    onResult({ query: buildQuery(name, number), name: name.trim(), number: String(number || '').trim() });
  };

  const onEnter = (e) => { if (e.key === 'Enter') { e.preventDefault(); research(); } };

  const inputCls = 'w-full bg-slate-950 border border-slate-700 focus:border-cyan-500 text-slate-100 rounded-lg px-3 py-2 text-sm outline-none';
  const btnCls = 'block text-center cursor-pointer font-black py-3 rounded-xl text-sm transition-colors';
  const disabled = busy ? 'opacity-50 pointer-events-none' : '';

  return (
    <div className="fixed inset-0 z-[80] bg-slate-950 flex flex-col text-slate-100">
      <div className="flex items-center justify-between px-4 py-3 border-b border-cyan-500/20 bg-slate-900">
        <h2 className="font-black text-cyan-400 text-sm">📷 Karte scannen</h2>
        <button onClick={onClose} className="text-xs bg-slate-800 px-3 py-1.5 rounded-lg text-slate-300 hover:text-rose-400">Schließen ✕</button>
      </div>

      <div className="flex-1 overflow-y-auto p-4">
        <div className="max-w-xl mx-auto space-y-4">
          <p className="text-xs text-slate-400">
            Fotografiere eine einzelne Karte gerade von oben, ohne Blitz-Reflexe. Name und Nummer werden erkannt und die Karte wird in der Datenbank gesucht.
          </p>

          <div className="grid grid-cols-2 gap-2">
            <label className={`${btnCls} bg-cyan-500 hover:bg-cyan-400 text-slate-950 ${disabled}`}>
              📷 Kamera
              <input type="file" accept="image/*" capture="environment" onChange={onFile} className="hidden" disabled={busy} />
            </label>
            <label className={`${btnCls} bg-slate-800 hover:bg-slate-700 text-cyan-300 border border-cyan-500/30 ${disabled}`}>
              🖼️ Aus Galerie
              <input type="file" accept="image/*" onChange={onFile} className="hidden" disabled={busy} />
            </label>
          </div>

          {mode === 'collection' && onSeriesChange && (
            <label className="flex items-center gap-2 text-xs text-slate-300">
              <input type="checkbox" checked={!!series} onChange={(e) => onSeriesChange(e.target.checked)} className="accent-cyan-500" />
              Serienmodus: nach dem Hinzufügen direkt die nächste Karte scannen
            </label>
          )}

          {busy && (
            <div className="bg-slate-900 border border-cyan-500/30 rounded-xl p-3 text-xs text-cyan-300 flex items-center gap-2">
              <span className="animate-spin">⚡</span> {status || 'Bitte warten …'} <span className="text-slate-500">(nach Inaktivität braucht der Server evtl. bis zu einer Minute)</span>
            </div>
          )}

          {error && (
            <div className="bg-rose-500/10 border border-rose-500/30 rounded-xl p-3 space-y-2">
              <p className="text-xs text-rose-300">{error}</p>
              {dataUrlRef.current && !busy && (
                <button onClick={() => analyze(dataUrlRef.current)} className="text-[11px] font-black px-3 py-1.5 rounded-lg bg-cyan-500 hover:bg-cyan-400 text-slate-950">🔄 Erneut versuchen (gleiches Foto)</button>
              )}
            </div>
          )}

          {preview && (
            <div className="flex gap-3 items-start">
              <img src={preview} alt="Scan" className="w-24 rounded-lg border border-slate-700 shrink-0" />
              {scanned && (
                <div className="flex-1 space-y-2">
                  <p className="text-[10px] text-slate-400">Erkannt – bei Bedarf korrigieren:</p>
                  <input value={name} onChange={(e) => setName(e.target.value)} onKeyDown={onEnter} placeholder="Name" className={inputCls} />
                  <input value={number} onChange={(e) => setNumber(e.target.value)} onKeyDown={onEnter} placeholder="Nummer, z. B. 44/102" className={inputCls} />
                  {(meta.set || meta.language) && (
                    <p className="text-[10px] text-slate-500">
                      {meta.language ? `Sprache: ${LANG_LABEL[meta.language] || meta.language}` : ''}{meta.language && meta.set ? ' · ' : ''}{meta.set ? `Set: ${meta.set}` : ''}
                    </p>
                  )}
                  {mode === 'collection' && (
                    <div>
                      <select
                        value={variant}
                        onChange={(e) => { setVariant(e.target.value); setVariantAuto(false); }}
                        className={inputCls}
                      >
                        <option value="">Variante: Standard</option>
                        <option value="normal">Normal</option>
                        <option value="reverse">Reverse Holo</option>
                        <option value="holo">Holo</option>
                      </select>
                      {variantAuto && variant && <p className="text-[10px] text-amber-300 mt-0.5">Automatisch erkannt – bitte prüfen. Wird nur übernommen, wenn es die Variante für die Karte gibt.</p>}
                    </div>
                  )}
                  <button onClick={research} disabled={busy || !name.trim()} className="text-[11px] font-bold text-cyan-400 hover:underline disabled:opacity-40">Neu suchen</button>
                </div>
              )}
            </div>
          )}

          {scanned && mode === 'search' && (
            <button onClick={takeToSearch} disabled={!name.trim()} className="w-full bg-cyan-500 hover:bg-cyan-400 disabled:opacity-40 text-slate-950 font-black py-3 rounded-xl text-sm">
              🔍 „{buildQuery(name, number)}“ in der Suche öffnen
            </button>
          )}

          {scanned && mode !== 'search' && (
            cards.length === 0 ? (
              <p className="text-xs text-amber-300">Keine passende Karte gefunden. Name/Nummer oben anpassen und „Neu suchen“ tippen.</p>
            ) : (
              <div className="space-y-2">
                <p className="text-xs font-bold text-slate-200">Treffer ({cards.length}) – Karte antippen zum Hinzufügen</p>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {cards.slice(0, 12).map((card) => (
                    <button key={card.id} onClick={() => onPick && onPick(card, mode === 'collection' ? (variant || null) : null, variantAuto)} className="text-left bg-slate-900 border border-slate-800 hover:border-cyan-500 rounded-xl p-2 space-y-1 transition-colors">
                      {Img
                        ? <Img src={card.images && card.images.small} alt={card.name} className="w-full rounded-lg" />
                        : <img src={card.images && card.images.small} alt={card.name} className="w-full rounded-lg" />}
                      <p className="text-xs font-bold text-slate-200 truncate">{plain(card.name)}{card.number ? <span className="text-slate-500 font-normal"> #{card.number}</span> : null}</p>
                      <p className="text-[10px] text-slate-400 truncate">{(card.set && card.set.name) || 'Unbekanntes Set'}</p>
                      <p className="text-[11px] text-cyan-400 font-bold">
                        {eur(watchPrice(card.cardmarket && card.cardmarket.prices))}
                        {scores[card.id] != null ? <span className="text-slate-500 font-normal"> · {scores[card.id]} % ähnlich</span> : null}
                      </p>
                      {owned && <OwnedBadge info={owned.get(card.id)} />}
                    </button>
                  ))}
                </div>
              </div>
            )
          )}

          {mode === 'collection' && <ScanHistory history={history} onUndo={onUndo} Img={Img} compact />}
        </div>
      </div>
    </div>
  );
}

// Komplettierungs-Kosten: "Was kostet es, die fehlenden Karten zu besorgen?"
// + Knopf "Alle in die Wishlist". Wird für Sets (SetsView) und Binder benutzt.
import React, { useState, useEffect, useMemo } from 'react';
import { collection as fsCollection, onSnapshot, writeBatch, doc } from 'firebase/firestore';
import { db } from './firebase';
import { fetchPrices, watchPrice } from './priceData';

const eur = (n) => `${(Number(n) || 0).toFixed(2).replace('.', ',')} €`;
const isReal = (id) => !!id && !String(id).startsWith('custom-');

// Kleiner Preis-Zwischenspeicher: Firestore-/Backend-Preise werden pro Karte 30 Min. gemerkt,
// damit z. B. "alle Binder" und danach ein einzelner Binder nicht noch einmal laden.
const memo = new Map(); // id -> { at, data }
const MEMO_TTL_MS = 30 * 60 * 1000;

async function pricesFor(ids, api, onProgress) {
  const now = Date.now();
  const out = {};
  const need = [];
  ids.forEach((id) => {
    const hit = memo.get(id);
    if (hit && now - hit.at < MEMO_TTL_MS) out[id] = hit.data; else need.push(id);
  });
  const cached = ids.length - need.length;
  if (onProgress) onProgress(cached, ids.length);
  if (need.length > 0) {
    const got = await fetchPrices(need, api, { onProgress: (d) => onProgress && onProgress(cached + d, ids.length) });
    need.forEach((id) => {
      if (got[id]) { memo.set(id, { at: now, data: got[id] }); out[id] = got[id]; }
    });
  }
  return out;
}

// cards: [{ id, name, image, localId, setName }] – die Karten, die noch fehlen
export function CompletionPanel({ title, hint, cards, api, uid, watchIds, Img }) {
  const list = useMemo(() => {
    const seen = new Set();
    const out = [];
    for (const c of cards || []) {
      if (!c || !isReal(c.id) || seen.has(c.id)) continue;
      seen.add(c.id); out.push(c);
    }
    return out;
  }, [cards]);
  const sig = list.map((c) => c.id).join('|');

  const [prices, setPrices] = useState(null);
  const [busy, setBusy] = useState(''); // '' | 'calc' | 'wish'
  const [progress, setProgress] = useState('');
  const [msg, setMsg] = useState('');

  useEffect(() => { setPrices(null); setMsg(''); }, [sig]);

  const rows = useMemo(
    () => (prices ? list.map((c) => ({ ...c, price: watchPrice(prices[c.id]?.prices) })) : []),
    [prices, list]
  );
  const total = rows.reduce((s, r) => s + r.price, 0);
  const unknown = rows.filter((r) => !(r.price > 0)).length;
  const top = [...rows].sort((a, b) => b.price - a.price).slice(0, 10);
  const toAdd = list.filter((c) => !watchIds.has(c.id));

  const calc = async () => {
    if (busy) return;
    setBusy('calc'); setMsg(''); setProgress(`0 / ${list.length}`);
    try {
      const got = await pricesFor(list.map((c) => c.id), api, (d, t) => setProgress(`${d} / ${t}`));
      setPrices(got);
    } catch (e) {
      setMsg(e.name === 'AbortError'
        ? 'Der Server hat zu lange nicht geantwortet (Render schläft evtl.). Bitte in ca. 1 Minute nochmal versuchen.'
        : 'Preise konnten nicht geladen werden: ' + (e.message || 'Unbekannter Fehler'));
    } finally {
      setBusy(''); setProgress('');
    }
  };

  const addAll = async () => {
    if (busy || !uid || toAdd.length === 0) return;
    if (!window.confirm(`${toAdd.length} Karten zur Watchlist hinzufügen?`)) return;
    setBusy('wish'); setMsg('');
    let added = 0; let failed = 0;
    try {
      for (let i = 0; i < toAdd.length; i += 30) {
        setProgress(`Lade Kartendaten … ${Math.min(i + 30, toAdd.length)} / ${toAdd.length}`);
        const ids = toAdd.slice(i, i + 30).map((c) => c.id);
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 120000);
        const res = await fetch(`${api}/api/cards/bulk`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          signal: controller.signal,
          body: JSON.stringify({ ids })
        });
        clearTimeout(timer);
        if (!res.ok) throw new Error(`Server antwortet mit Status ${res.status}`);
        const full = (await res.json()).cards || [];
        failed += ids.length - full.length;
        const batch = writeBatch(db);
        const now = Date.now();
        full.forEach((card) => batch.set(doc(db, 'users', uid, 'watchlist', card.id), { ...card, addedAt: now }));
        if (full.length > 0) await batch.commit();
        added += full.length;
      }
      setMsg(`${added} Karten stehen jetzt auf der Watchlist. ★` + (failed ? ` ${failed} konnten nicht geladen werden.` : ''));
    } catch (e) {
      const part = added > 0 ? ` (${added} wurden schon hinzugefügt)` : '';
      setMsg('Fehlgeschlagen: ' + (e.name === 'AbortError' ? 'Server hat zu lange nicht geantwortet' : (e.message || 'Unbekannter Fehler')) + part);
    } finally {
      setBusy(''); setProgress('');
    }
  };

  if (list.length === 0) return null;

  return (
    <div className="bg-slate-950 border border-cyan-500/30 rounded-xl p-3 space-y-3 mb-3">
      {title && <h4 className="text-sm font-bold text-slate-100">{title}</h4>}
      {hint && <p className="text-[10px] text-slate-500">{hint}</p>}

      {prices ? (
        <div className="space-y-2">
          <div className="flex justify-between items-end gap-2">
            <div>
              <p className="text-[10px] text-slate-400 uppercase tracking-wider">Kosten bis komplett</p>
              <p className="text-2xl font-black text-cyan-300">{eur(total)}</p>
            </div>
            <p className="text-[11px] text-slate-400 text-right">
              {list.length} Karten (Cardmarket-Trend)
              {unknown > 0 && <><br /><span className="text-amber-300">{unknown} ohne Preis</span></>}
            </p>
          </div>
          {top.length > 0 && top[0].price > 0 && (
            <div className="space-y-1 pt-2 border-t border-slate-800">
              <p className="text-[10px] text-slate-500">Teuerste fehlende Karten</p>
              {top.filter((r) => r.price > 0).map((r) => (
                <div key={r.id} className="flex items-center gap-2 text-xs">
                  {Img && <Img src={r.image} alt={r.name} className="w-7 rounded" />}
                  <span className="flex-1 min-w-0 truncate text-slate-300">
                    {r.name}{r.localId ? <span className="text-slate-500"> #{r.localId}</span> : null}
                    {r.setName ? <span className="text-slate-500"> · {r.setName}</span> : null}
                  </span>
                  <span className="text-cyan-400 font-bold whitespace-nowrap">{eur(r.price)}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <p className="text-xs text-slate-400">{list.length} Karten fehlen. Die Kosten werden aus den aktuellen Cardmarket-Trends berechnet.</p>
      )}

      <div className="flex gap-2">
        <button
          onClick={calc}
          disabled={!!busy}
          className="flex-1 bg-cyan-500 hover:bg-cyan-400 disabled:opacity-50 text-slate-950 text-xs font-black py-2.5 rounded-lg transition-colors"
        >
          {busy === 'calc' ? `⏳ ${progress}` : prices ? '🔄 Neu berechnen' : '💶 Kosten berechnen'}
        </button>
        <button
          onClick={addAll}
          disabled={!!busy || toAdd.length === 0}
          className="flex-1 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-cyan-300 border border-cyan-500/30 text-xs font-black py-2.5 rounded-lg transition-colors"
        >
          {busy === 'wish' ? `⏳ ${progress}` : toAdd.length === 0 ? '★ Alle schon auf der Wishlist' : `★ Alle in die Wishlist (${toAdd.length})`}
        </button>
      </div>
      {msg && <p className="text-[11px] text-slate-300">{msg}</p>}
    </div>
  );
}

// Karten, die in Bindern liegen, aber noch nicht in der Collection sind ("noch nicht gekauft").
export function BinderCompletion({ uid, collection, watchIds, api, Img }) {
  const [binders, setBinders] = useState(null);
  const [denied, setDenied] = useState(false);

  useEffect(() => {
    if (!uid) return undefined;
    return onSnapshot(
      fsCollection(db, 'users', uid, 'binders'),
      (snap) => { setBinders(snap.docs.map((d) => ({ ...d.data(), id: d.id }))); setDenied(false); },
      (err) => { console.warn('Binder nicht lesbar:', err.code); setDenied(true); setBinders([]); }
    );
  }, [uid]);

  const owned = useMemo(() => new Set(collection.map((c) => String(c.id))), [collection]);

  const groups = useMemo(() => (binders || []).map((b, i) => {
    const seen = new Set();
    const cards = [];
    Object.values(b.slots || {}).forEach((s) => {
      const id = s && s.id ? String(s.id) : '';
      if (!isReal(id) || owned.has(id) || seen.has(id)) return;
      seen.add(id);
      cards.push({
        id,
        name: s.name || id,
        image: s.customImage || s.image || (s.images && s.images.small) || '',
        localId: s.localId || s.number || '',
        setName: s.setName || (s.set && s.set.name) || ''
      });
    });
    return { id: b.id, name: b.name || b.title || `Binder ${i + 1}`, cards };
  }).filter((g) => g.cards.length > 0), [binders, owned]);

  const all = useMemo(() => {
    const seen = new Set();
    const out = [];
    groups.forEach((g) => g.cards.forEach((c) => { if (!seen.has(c.id)) { seen.add(c.id); out.push(c); } }));
    return out;
  }, [groups]);

  if (binders === null) return null;
  if (denied) return null; // ohne Leserechte gar nichts anzeigen
  if (groups.length === 0) return null;

  return (
    <details className="bg-slate-900 border border-slate-800 rounded-xl p-3 shadow-md">
      <summary className="cursor-pointer text-sm font-bold text-slate-200">
        💶 Noch nicht gekaufte Binder-Karten ({all.length}) – Kosten &amp; Wishlist
      </summary>
      <div className="mt-3 space-y-3">
        <p className="text-[10px] text-slate-500">Karten, die in einem Binder liegen, aber (noch) nicht in deiner Collection sind.</p>
        {groups.length > 1 && (
          <CompletionPanel
            title="Alle Binder zusammen"
            cards={all}
            api={api}
            uid={uid}
            watchIds={watchIds}
            Img={Img}
          />
        )}
        {groups.map((g) => (
          <details key={g.id} className="bg-slate-950 border border-slate-800 rounded-lg p-2">
            <summary className="cursor-pointer text-xs font-bold text-slate-300">
              {g.name} <span className="text-slate-500 font-normal">· {g.cards.length} fehlen</span>
            </summary>
            <div className="mt-2">
              <CompletionPanel cards={g.cards} api={api} uid={uid} watchIds={watchIds} Img={Img} />
            </div>
          </details>
        ))}
      </div>
    </details>
  );
}

